function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[name]||ICON.file}</svg>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}function fmt(v){return Number(v||0).toLocaleString('id-ID')}function date(v){if(!v)return '—';try{return new Date(v.slice(0,10)+'T00:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})}catch{return v}}function nameInitials(s){return (s||'U').trim().split(/\s+/).slice(0,2).map(v=>v[0]||'').join('').toUpperCase()}
function status(v){let lbl={active:'Aktif',inactive:'Tidak aktif',draft:'Menunggu SK',menunggu:'Menunggu',terverifikasi:'Terverifikasi'};return `<span class="status-pill ${esc(v)}">${esc(lbl[v]||v||'Belum diisi')}</span>`}
function empty(t='Belum ada data',d='Data akan muncul setelah dimasukkan dan disimpan.'){return `<div class="empty">${icon('folder',34)}<h3>${esc(t)}</h3><p>${esc(d)}</p></div>`}function title(t,sub,actions=''){return `<div class="page-head"><div><h1>${esc(t)}</h1><p>${esc(sub||'')}</p></div><div class="page-actions">${actions}</div></div>`}function btn(t,act,variant='primary',extra=''){return `<button class="btn ${variant}" data-act="${esc(act)}" ${extra}>${t}</button>`}function panel(t,sub,body,link=''){return `<section class="panel"><div class="panel-header"><div><h3>${t}</h3>${sub?`<p>${sub}</p>`:''}</div>${link}</div>${body}</section>`}
const perms=(...roles)=>!!me&&roles.includes(me.role);const SK_VIEWERS=['superadmin','admin_wib','ketum','sekjen','waketum','dpw','auditor'],SES_SK_VIEWERS=[...SK_VIEWERS,'ses_admin','ses_director'],SES_SK_EDITORS=['superadmin','ses_director'];
async function api(path,opts={}){let headers={'Accept':'application/json',...(opts.headers||{})};if(opts.body&&!(opts.body instanceof FormData))headers['Content-Type']='application/json';if(opts.method&&opts.method!=='GET')headers['x-csrf-token']=csrf;let res=await fetch(path,{credentials:'same-origin',...opts,headers});let t=res.headers.get('content-type')||'';let data=t.includes('application/json')?await res.json():await res.text();if(!res.ok){if(res.status===401&&me){me=null;showLogin()}throw Error((data.detail&&typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data))||`Kesalahan ${res.status}`)}return data}
function toast(text,error=false){let el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=text;$('#toastRegion').append(el);setTimeout(()=>el.remove(),4800)}
function startNav(){let allowed=menus.filter(([k])=>!(k==='audit'&&!perms('superadmin','ketum','sekjen','waketum','auditor'))&&!(k==='sk'&&!perms(...SES_SK_VIEWERS))&&!(k==='kta'&&!perms(...KTA_VIEWERS))&&(me.role!=='pengurus'||['kegiatan','dokumen','pengaturan'].includes(k)));$('#sideNav').innerHTML=allowed.map(([k,label,ico],i)=>`${k==='kantor'||k==='audit'?'<div class="nav-divider"></div>':''}<button class="nav-item ${k===page?'active':''}" data-nav="${k}">${icon(ico)} <span>${label}</span></button>`).join('');$('#logoutIcon').innerHTML=icon('logout');$('#accountName').textContent=me.full_name;$('#accountRole').textContent=roleLabels[me.role]||me.role;$('#avatar').textContent=nameInitials(me.full_name);$('#footerMode').textContent='Sistem internal · '+(cache.config?.demo?'Mode demonstrasi':'Operasional lokal')}
function showLogin(){$('#loginView').hidden=false;$('#appShell').hidden=true;closeModal();closeDrawer()};function showApp(){$('#loginView').hidden=true;$('#appShell').hidden=false;if(me.role==='pengurus'&&!['kegiatan','dokumen','pengaturan'].includes(page))page='kegiatan';$('#crumbs').innerHTML='Ruang kerja / <b>'+esc(PATH[page])+'</b>';startNav();render()}
$('#loginForm').onsubmit=async e=>{e.preventDefault();let b=$('#loginButton');b.disabled=true;b.textContent='Memeriksa akun...';$('#loginError').hidden=true;try{await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#loginUsername').value,password:$('#loginPassword').value})});me=await api('/api/me');csrf=me.csrf;cache.config=await api('/api/config');showApp()}catch(ex){$('#loginError').textContent=ex.message;$('#loginError').hidden=false}finally{b.disabled=false;b.innerHTML='Masuk ke aplikasi <span>→</span>'}};$('#togglePassword').onclick=()=>{let inp=$('#loginPassword');inp.type=inp.type==='password'?'text':'password'};
$('#logoutBtn').onclick=async()=>{try{await api('/api/logout',{method:'POST'})}catch{}me=null;showLogin()};$('#mobileToggle').onclick=()=>$('#sidebar').classList.toggle('open');
document.addEventListener('click',e=>{let a=e.target.closest('[data-nav]');if(a){navigate(a.dataset.nav)} });function navigate(p){page=p;pageNo=1;filter={q:'',level:'',status:''};skFilter={q:'',level:'',province:'',status:'',code:'',jenis:''};histFilter={q:'',province:'',level:'',status:''};repFilter={province:'',city:'',district:'',periode:'',status:'',q:''};$('#sidebar').classList.remove('open');$$('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.nav===p));$('#crumbs').innerHTML='Ruang kerja / <b>'+esc(PATH[p])+'</b>';render()}
async function render(){let main=$('#mainContent');main.innerHTML='<div class="panel"><p class="muted">Memuat halaman...</p></div>';try{if(page==='dashboard')await drawDashboard();if(page==='pengurus')await drawPeople();if(page==='ses')await drawSES();if(page==='sk')await drawSK();if(page==='kta')await drawKTA();if(page==='kantor')await drawOffices();if(page==='kegiatan')await drawActivities();if(page==='peluang')await drawOpportunities();if(page==='dokumen')await drawDocuments();if(page==='evaluasi')await drawEvaluations();if(page==='riwayat')await drawHistory();if(page==='audit')await drawAudits();if(page==='pengaturan'){await drawSettings();if(me.role!=='pengurus')$('#mainContent').insertAdjacentHTML('beforeend',dukcapilPanel())}}catch(ex){main.innerHTML=title(PATH[page]||'Halaman','Terjadi kendala saat memuat data')+`<div class="panel"><p class="form-error">${esc(ex.message)}</p>${btn('Muat ulang','reload','primary')}</div>`}};
function metric(label,n,foot,ico='dashboard',tone=''){return `<section class="metric-card"><div class="metric-top"><div class="metric-icon ${tone}">${icon(ico)}</div><span class="stat-dash">• • •</span></div><div class="metric-label">${label}</div><div class="metric-value">${fmt(n)}</div><div class="metric-bottom">${foot}</div></section>`}
function pie(data,colors){let arr=Object.entries(data).filter(x=>x[1]>=0),sum=arr.reduce((s,x)=>s+x[1],0),r=83,circ=2*Math.PI*r;let pos=0,circles=arr.map(([label,n],i)=>{let len=sum?(n/sum)*circ:0,off=pos;pos+=len;return `<circle r="${r}" cx="110" cy="110" fill="none" stroke="${colors[i%colors.length]}" stroke-width="25" stroke-dasharray="${len.toFixed(3)} ${(circ-len).toFixed(3)}" stroke-dashoffset="${(-off).toFixed(3)}"/>`}).join('');return `<div class="pie-layout"><div class="pie-chart"><svg viewBox="0 0 220 220"><circle r="${r}" cx="110" cy="110" fill="none" stroke="#edf0f2" stroke-width="25"/>${circles}</svg><div class="pie-center"><strong>${fmt(sum)}</strong><span>Total data</span></div></div><div class="legend">${arr.map(([label,n],i)=>`<div class="legend-item"><span class="legend-name"><i class="legend-dot" style="background:${colors[i%colors.length]}"></i>${esc(label)}</span><span class="legend-val">${fmt(n)} <span class="muted small">${sum?Math.round(100*n/sum):0}%</span></span></div>`).join('')}</div></div>`}
function cardN(label,n,foot,ico,tone=''){return metric(label,n,foot,ico,tone)}
function hbars(items,max){max=max||Math.max(1,...items.map(x=>x[1]));return `<div class="stats-list">${items.map(([l,v,c,sub])=>`<div class="bar-item"><div class="bar-label"><span>${esc(l)}</span><strong>${fmt(v)}${sub?` <span class="muted small">${esc(sub)}</span>`:''}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${max?Math.max(v?2:0,100*v/max):0}%;${c?'background:'+c:''}"></div></div></div>`).join('')}</div>`}
function progress(label,n,total,hint){let pct=total?Math.round(100*n/total):0;return `<div class="bar-item"><div class="bar-label"><span>${esc(label)}</span><strong>${fmt(n)}/${fmt(total)} <span class="muted small">${pct}%</span></strong></div><div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${pct>=80?'#258467':pct>=40?'#e2ad53':'#d25a67'}"></div></div>${hint?`<small class="muted tiny">${esc(hint)}</small>`:''}</div>`}
function colChart(data){let max=Math.max(1,...data.map(x=>Math.max(x.aktif,x.laporan))),W=420,H=190,bw=26,gap=(W-40)/data.length;return `<svg class="col-chart" viewBox="0 0 ${W} ${H+34}" role="img" aria-label="Grafik keaktifan per triwulan">${[0,0.5,1].map(t=>`<line x1="30" x2="${W}" y1="${10+H*(1-t)}" y2="${10+H*(1-t)}" stroke="#edf0f2"/><text x="24" y="${14+H*(1-t)}" text-anchor="end" font-size="10" fill="#7a8590">${Math.round(max*t)}</text>`).join('')}${data.map((x,i)=>{let cx=40+gap*i+gap/2,h1=H*x.aktif/max,h2=H*x.laporan/max;return `<rect x="${cx-bw-2}" y="${10+H-h1}" width="${bw}" height="${h1}" rx="3" fill="#aa2636"><title>${x.aktif} pengurus aktif melapor</title></rect><rect x="${cx+2}" y="${10+H-h2}" width="${bw}" height="${h2}" rx="3" fill="#e2ad53"><title>${x.laporan} laporan diterima</title></rect><text x="${cx}" y="${H+26}" text-anchor="middle" font-size="11" fill="#3d4851">${esc(x.periode)}</text>`}).join('')}</svg><div class="legend inline"><span><i class="legend-dot" style="background:#aa2636"></i>Ketua aktif yang laporannya diterima</span><span><i class="legend-dot" style="background:#e2ad53"></i>Jumlah laporan diterima</span></div>`}
async function drawDashboard(){let d=await api('/api/dashboard/v11');cache.dashboard=d;let sesOnly=d.ses_only,P=d.pengurus,S=d.ses,R=d.reports;
 const nme=sesOnly?'Dashboard SES Group':'Dashboard Nasional';
 let cards=sesOnly?[cardN('Menunggu persetujuan SES',S.menunggu_ses,'Antrean pemeriksaan Petugas SES','clock','amber'),cardN('Menunggu pengesahan',S.menunggu_pengesahan,'Disetujui Petugas SES, menunggu Direksi','briefcase','blue'),cardN('SK SES diterbitkan',S.diterbitkan,`${fmt(S.aktif)} Kepala Cabang aktif`,'checklist','teal'),cardN('Perlu perbaikan / ditolak',S.perlu_perbaikan+S.ditolak,'Dikembalikan ke pengaju','file')]
  :[cardN('Pengurus aktif',P.active,`${fmt(P.draft)} menunggu SK`,'users','teal'),cardN('Pengurus tidak aktif',P.inactive,'Riwayat tetap tersimpan','history'),cardN('SK WIB diterbitkan',d.sk_wib.issued,'Aktif & riwayat','file'),cardN('SK SES menunggu Ihsan',S.menunggu_ses,`${fmt(S.menunggu_pengesahan)} menunggu pengesahan Direksi`,'clock','amber'),cardN('SK SES diterbitkan',S.diterbitkan,`${fmt(S.aktif)} penugasan aktif`,'briefcase','blue'),cardN('Laporan diterima',R.triwulan_ini,`Triwulan ${esc(d.current_quarter)} · ${fmt(R.diajukan+R.diperiksa)} menunggu`,'clipboard','teal')];
 let provRows=d.provinces.slice(0,cache.dashAllProv?99:10).map(x=>[`<b class="data-name">${esc(x.province)}</b>`,`<b>${fmt(x.active)}</b>`,fmt(x.DPW),fmt(x.DPD),fmt(x.DPC),fmt(x.PAC),fmt(x.draft),fmt(x.inactive)]);
 const reasons=r=>esc((r||'—').replaceAll('_',' '));
 $('#mainContent').innerHTML=title(nme,'Data aktual dari database: struktur kepengurusan, SK, laporan kegiatan, legalitas, dan pengawasan.',`<span class="date-chip">${new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span>`)+
 (d.demo?'<div class="role-banner"><b>Mode demonstrasi</b><span>Data pada mode demo dipakai untuk uji coba.</span></div>':'')+
 `<div class="cards-auto">${cards.join('')}</div>`+
 (sesOnly?'':`<div class="main-grid">${panel('Distribusi pengurus aktif','Pengurus aktif per jenjang DPW, DPD, DPC, PAC',pie(d.levels,['#aa2636','#df8d91','#f1c3c6','#6b7079']))}${panel('Keaktifan pengurus per triwulan','Ketua aktif dengan laporan kegiatan diterima DPP',colChart(d.activity))}</div>`)+
 `<div class="main-grid">${panel('Pengajuan SK SES Group','Alur: Pengaju → Petugas SES → Direksi → SK terbit',hbars([['Menunggu persetujuan SES',S.menunggu_ses,'#e2ad53'],['Menunggu pengesahan Direksi',S.menunggu_pengesahan,'#3b7fc4'],['Perlu perbaikan',S.perlu_perbaikan,'#d25a67'],['Ditolak',S.ditolak,'#6b7079'],['SK diterbitkan',S.diterbitkan,'#258467']]),`<button class="panel-link" data-nav="sk">Buka SK SES →</button>`)}${sesOnly?panel('Legalitas SES Group','Dokumen kantor/cabang terverifikasi',`<div class="stats-list">${progress('Salinan akta SES notarial',d.legal_ses.akta,d.legal_ses.offices)}${progress('Banner SES Group',d.legal_ses.banner,d.legal_ses.offices)}</div>`):panel('Laporan kegiatan WIB','Status seluruh laporan wilayah',hbars([['Diajukan',R.diajukan,'#e2ad53'],['Diperiksa DPP',R.diperiksa,'#3b7fc4'],['Perlu perbaikan',R.perlu_perbaikan,'#d25a67'],['Diterima',R.diterima,'#258467']]),`<button class="panel-link" data-nav="kegiatan">Buka laporan →</button>`)}</div>`+
 (sesOnly?'':`<div class="main-grid">${panel('Kelengkapan & legalitas kantor','Berdasarkan dokumen kantor yang sudah diverifikasi',`<div class="stats-list">${progress('Kesbangpol',d.kesbangpol.verified,d.kesbangpol.offices)}${progress('Legalitas SES (salinan akta notarial)',d.legal_ses.akta,d.legal_ses.offices)}${progress('Banner SES Group',d.legal_ses.banner,d.legal_ses.offices)}${progress('Alamat sekretariat',d.kantor.alamat,d.kantor.offices)}${progress('Foto kantor (depan & dalam)',d.kantor.foto,d.kantor.offices)}</div>${d.kantor.offices?'':'<p class="muted small">Belum ada kantor yang dicatat.</p>'}`,`<button class="panel-link" data-nav="kantor">Kantor & Legalitas →</button>`)}${panel(`Pengurus yang perlu dievaluasi (${fmt(d.to_evaluate_total)})`,'Ketua aktif ≥ 90 hari tanpa laporan diterima triwulan ini & sebelumnya',d.to_evaluate.length?`<div class="stats-list">${d.to_evaluate.map(x=>`<div class="notice"><span class="notice-icon">${icon('clock')}</span><div><strong>${esc(x.full_name)}</strong><small>${esc(x.title)} ${esc(x.level)} · ${esc(x.wilayah)} · ${fmt(x.days)} hari menjabat</small></div></div>`).join('')}</div>`:empty('Tidak ada','Semua Ketua aktif sudah melapor atau baru menjabat.'),`<button class="panel-link" data-nav="evaluasi">Buka evaluasi →</button>`)}</div>`)+
 (sesOnly?'':`<h2 class="content-section-title">Statistik kepengurusan per wilayah</h2><section class="table-panel">${table(['Provinsi','Aktif','DPW','DPD','DPC','PAC','Menunggu SK','Tidak aktif'],provRows)}${d.provinces.length>10?`<div class="table-footer"><span>${fmt(d.provinces.length)} provinsi</span>${btn(cache.dashAllProv?'Tampilkan 10 teratas':'Tampilkan semua','dash_prov','small')}</div>`:''}</section>`)+
 `<div class="main-grid">${sesOnly?'':panel('Pemberhentian & pergantian terbaru','Jabatan yang berakhir — riwayat tidak dihapus',d.ended.length?`<div class="stats-list">${d.ended.map(x=>`<div class="notice"><span class="notice-icon">${icon('history')}</span><div><strong>${esc(x.full_name)} · ${esc(x.title)} ${esc(x.level)}</strong><small>${esc(x.district||x.city||x.province)} · berakhir ${date(x.ended_at)} · ${reasons(x.end_reason)}</small></div></div>`).join('')}</div>`:empty('Belum ada','Belum ada jabatan yang diakhiri.'),`<button class="panel-link" data-nav="riwayat">Penugasan & Riwayat →</button>`)}${panel('Riwayat perubahan','Pengesahan, pemberhentian, dan pengajuan terbaru',d.changes.length?`<div class="stats-list">${d.changes.map(x=>`<div class="notice"><span class="notice-icon green">${icon('shield')}</span><div><strong>${esc(AUDIT_LABEL[x.action]||x.action)}</strong><small>${esc(x.actor||'Sistem')} · ${date(x.created_at)} ${esc((x.detail||'').slice(0,80))}</small></div></div>`).join('')}</div>`:empty('Belum ada perubahan'))}</div>`}
const AUDIT_LABEL={approve_wib:'SK WIB disahkan',terminate_wib:'Jabatan WIB diakhiri',approve_ses:'SK SES diterbitkan',terminate_ses:'Penugasan SES diakhiri',next_period:'Periode kepengurusan baru',submit_ses:'Pengajuan SK SES',review_ses:'Pemeriksaan SK SES',import_data_sk:'Impor data pengurus',import_ses:'Impor Kepala Cabang SES'};
const SES_TONE={draft:'draft',menunggu_ses:'menunggu',perlu_perbaikan:'review',ditolak:'inactive',menunggu_pengesahan:'menunggu',disetujui:'active',sk_diterbitkan:'active'};
function sesPill(x){return `<span class="status-pill ${SES_TONE[x.review_status]||'draft'}">${esc(x.review_label||x.review_status||'Draft')}</span>`}
function sesActions(x,d){let b=[];if((d.can_check&&x.review_status==='menunggu_ses')||(d.can_ratify&&x.review_status==='menunggu_pengesahan'))b.push(btn(x.review_status==='menunggu_ses'?'Periksa':'Sahkan / tinjau','ses_review','small primary',`data-id="${x.id}"`));else b.push(btn('Rincian','ses_review','small',`data-id="${x.id}"`));
 if(d.can_submit&&['perlu_perbaikan','ditolak','draft'].includes(x.review_status)&&x.wib_status==='active')b.push(btn(x.review_status==='draft'?'Ajukan':'Ajukan ulang','ses_resubmit','small',`data-id="${x.id}"`));return b.join('')}
async function formSESReview(id){let d=await api('/api/ses/'+id+'/timeline'),x=d.item,st=x.review_status,me_check=perms('superadmin','ses_admin')&&st==='menunggu_ses',me_ratify=perms('superadmin','ses_director')&&st==='menunggu_pengesahan',act=me_check||me_ratify;
 let docs=d.docs.length?d.docs.map(f=>`<div class="notice"><span class="notice-icon ${f.status==='terverifikasi'?'green':''}">${icon('file')}</span><div><a href="/api/documents/${f.id}/download" target="_blank" rel="noopener">${esc(f.original_name)}</a><small>${esc(DOC_LABEL[f.doc_type]||f.doc_type)} · ${esc(f.status)} · ${date(f.uploaded_at)}</small></div></div>`).join(''):'<p class="form-error small">Belum ada dokumen pribadi (mis. KTP, SK WIB) yang diunggah.</p>';
 let log=d.log.map(l=>`<div class="timeline-item"><b>${esc(d.steps[l.to_status]||l.to_status)}</b><small>${esc(l.actor_name||'Sistem')}${l.actor_role?' · '+esc(roleLabels[l.actor_role]||l.actor_role):''} · ${new Date(l.created_at).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}</small>${l.note?`<div class="small">${esc(l.note)}</div>`:''}</div>`).join('')||'<p class="muted small">Belum ada riwayat.</p>';
 let checks=[['Data pengurus',`${esc(x.full_name)} · JK ${esc(x.gender||'belum diisi')} · HP ${esc(x.phone||'—')}`,!!x.full_name],['Jabatan WIB',`${esc(x.title)} ${esc(x.level)} · ${esc(x.wib_sk_no||'SK WIB belum terbit')}`,x.wib_status==='active'],['Wilayah SES',`${esc(d.wilayah)} (kode ${esc(d.kode||'—')}), ${esc(x.province)}`,!d.problem],['Kursi Kepala Cabang',d.holder?`Masih dijabat ${esc(d.holder.full_name)} (${esc(d.holder.sk_no||'—')}) — ${d.replace_holder?'diajukan sebagai penggantian':'TIDAK ditandai penggantian'}`:'Kosong',!d.holder||d.replace_holder],['Dokumen administrasi',`${d.docs.length} berkas`,d.docs.length>0]];
 openModal('Pengajuan SK SES Kepala Cabang',`<div class="sk-preview" style="margin-bottom:12px"><div class="small"><b>Status:</b> ${sesPill({review_status:st,review_label:d.review_label})}</div><div class="small"><b>Nomor SK:</b> ${esc(d.nomor)}</div>${x.review_note?`<div class="small"><b>Catatan terakhir:</b> ${esc(x.review_note)}</div>`:''}<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap"><a class="btn small" href="/api/pdf/SES/${id}/SK" target="_blank" rel="noopener">${st==='sk_diterbitkan'?'Buka SK final (PDF)':'Pratinjau PDF'}</a>${st==='sk_diterbitkan'?`<a class="btn small" href="/api/pdf/SES/${id}/DOCX">${icon('download',13)} Word</a>`:''}<button class="btn small" type="button" data-act="detail" data-id="${x.person_id}">Profil pengurus</button></div></div>
 <h4 class="sk-sub">Pemeriksaan kelengkapan</h4>${checks.map(([k,v,ok])=>`<div class="check-row ${ok?'ok':'bad'}"><span>${ok?'✓':'!'}</span><div><b>${k}</b><small>${v}</small></div></div>`).join('')}
 <h4 class="sk-sub">Dokumen pengurus</h4>${docs}<h4 class="sk-sub">Riwayat persetujuan</h4>${log}<input type="hidden" name="id" value="${id}">
 ${act?`<h4 class="sk-sub">${me_check?'Keputusan Petugas SES':'Pengesahan Direksi SES Group'}</h4><div class="sk-mode">${me_check?'<label><input type="radio" name="action" value="setujui" checked> Setujui — teruskan ke Direksi</label>':'<label><input type="radio" name="action" value="sahkan" checked> Sahkan — SK langsung diterbitkan</label>'}<label><input type="radio" name="action" value="perbaikan"> Minta perbaikan</label><label><input type="radio" name="action" value="tolak"> Tolak</label></div>${area('Catatan (wajib untuk perbaikan/penolakan)','note','Tuliskan hasil pemeriksaan')}<p class="muted tiny">Identitas Anda, tanggal, dan waktu keputusan dicatat pada riwayat persetujuan dan log audit.</p>`:''}`,act?'Simpan keputusan':'Tutup',act?'ses_review':'close');
 if(!act){$('#modalForm').onsubmit=e=>{e.preventDefault();closeModal()};$('#modalForm [data-act=close_modal]').hidden=true}}
