 `<section class="table-panel">${table(['Tanggal','Kegiatan','Wilayah','Pelapor','Lampiran','Status',''],d.items.map(x=>[date(x.occurred_at)+`<span class="row-sub">${esc(x.periode)}</span>`,`<b class="data-name">${esc(x.title)}</b><span class="row-sub">${esc(x.category)} · ${esc(x.location||'—')}</span>`,`<span>${esc(x.district||x.city||x.province)}</span><span class="row-sub">${esc(x.level)} · ${esc(x.province)}</span>`,esc(x.full_name),`${fmt(x.n_foto)} foto · ${fmt(x.n_pdf)} PDF`,`<span class="status-pill ${REP_TONE[x.status]}">${esc(x.status_label)}</span>`,`<button class="linkish" data-act="open_report" data-id="${x.id}">Buka →</button>`]))}<div class="table-footer"><span>Menampilkan ${d.items.length} dari ${fmt(d.total)} laporan</span><div>${btn('‹ Sebelumnya','prev_rep','small',` ${pageNo===1?'disabled':''}`)} ${pageNo}/${Math.max(d.pages,1)} ${btn('Berikutnya ›','next_rep','small',` ${pageNo>=d.pages?'disabled':''}`)}</div></div></section>`;
