 <dl class="detail-list">${field('Pelapor',`${x.full_name} · ${x.level} ${[x.district,x.city,x.province].filter(Boolean).join(', ')}`)}${field('Tanggal kegiatan',date(x.occurred_at))}${field('Lokasi',x.location)}${field('Jenis kegiatan',x.category)}${field('Jumlah peserta',x.participants!=null?fmt(x.participants)+' orang':'')}${field('Tujuan',x.purpose)}${field('Uraian',x.description)}${field('Hasil',x.result)}${field('Kendala',x.obstacles)}${field('Rencana tindak lanjut',x.followup)}</dl>
