async function formSKTemplate(){let d=await api('/api/sk/template'),t=d.template,ro=!d.can_edit;
 const ta=(label,name,val,rows=4,hint='')=>`<label class="wide">${label}${hint?` <span class="muted tiny">${hint}</span>`:''}<textarea name="${name}" rows="${rows}" ${ro?'readonly':''}>${esc(val)}</textarea></label>`;
 const ti=(label,name,val,wide)=>`<label${wide?' class="wide"':''}>${label}<input name="${name}" value="${esc(val)}" ${ro?'readonly':''}></label>`;
 let imgs=Object.entries(d.images).map(([k,v])=>`<div class="sk-img"><div class="sk-img-box">${v.present?`<img src="/api/sk/template/image/${k}?t=${Date.now()}" alt="${esc(v.label)}">`:'<span class="muted tiny">Belum ada</span>'}</div><small>${esc(v.label)}</small>${v.needs_auth?(v.authorized?`<small class="auth ok">✓ Diotorisasi ${esc(v.authorized_by||'')} ${date(v.authorized_at)}</small>`:`<small class="auth bad">${v.present?'Belum diotorisasi Ketua Umum — tidak dipakai pada SK':'Belum diunggah'}</small>`)+(d.can_authorize&&v.present?(v.authorized?btn('Cabut','sk_img_revoke','small danger',`data-slot="${k}"`):btn('Otorisasi','sk_img_auth','small primary',`data-slot="${k}"`)):''):''}${ro?'':`<label class="btn small">Ganti gambar<input type="file" accept="image/png,image/jpeg" data-sk-image="${k}" hidden></label>`}</div>`).join('');
 openModal('Template SK WIB',`<p class="muted small">Berlaku untuk semua SK WIB. Isian otomatis yang bisa dipakai di teks: <code>{tingkat_kata}</code> <code>{tingkat_lengkap}</code> <code>{wilayah_judul}</code> <code>{wilayah_kesatu}</code> <code>{nama}</code> <code>{jabatan}</code> <code>{nomor}</code>.${d.updated_at?` Terakhir diubah ${date(d.updated_at)} oleh ${esc(d.updated_by||'—')}.`:''}</p><h4 class="sk-sub">Gambar</h4><p class="muted tiny">Seluruh SK WIB, termasuk draft, memuat tanda tangan Ketua Umum dan Sekretaris Jenderal seperti pada Template_SK_WIB.docx. Tanda tangan Ketua Umum menimpa sebagian logo/stempel WIB. Draft tetap diberi tanda air DRAFT.</p><div class="sk-images">${imgs}</div><h4 class="sk-sub">Template Word (.docx)</h4><div class="sk-img" style="flex-direction:row;align-items:center;justify-content:space-between;flex-wrap:wrap"><div><b class="small">${d.docx.present?'Template_SK_WIB.docx terpasang':'Belum ada template Word'}</b><br><small>${d.docx.present?'Field: '+d.docx.fields.map(f=>'«'+esc(f)+'»').join(' '):'Unggah template agar tombol Word aktif.'}</small></div><div style="display:flex;gap:6px">${d.docx.present?`<a class="btn small" href="/api/sk/template/docx">Unduh template</a>`:''}${ro?'':`<label class="btn small">Ganti template Word<input type="file" accept=".docx" data-sk-docx="1" hidden></label>`}</div></div><p class="muted tiny">Dokumen Word mengikuti isi file .docx; PDF mengikuti teks di bawah. Bila salah satu diubah, sesuaikan juga yang lain.</p><h4 class="sk-sub">Teks surat (untuk PDF)</h4><div class="form-grid">${ti('Kalimat pembuka','pembuka',t.pembuka,true)}${ti('Penerbit','penerbit',t.penerbit,true)}${ti('Periode','periode',t.periode)}${ti('Kota penetapan','kota',t.kota)}${ta('Menimbang (a, b, c, …)','menimbang',t.menimbang.join('\n'),9,'satu butir per baris')}${ta('Mengingat (1, 2, 3, …)','mengingat',t.mengingat.join('\n'),5,'satu butir per baris')}${ta('Kesatu — kalimat lanjutan','kesatu_lanjutan',t.kesatu_lanjutan,3)}${ti('Kedua','kedua',t.kedua,true)}${ta('Penetap (di atas tanda tangan)','penetap',t.penetap,2)}${ti('Nama penandatangan 1','ttd1_nama',t.ttd1_nama)}${ti('Jabatan penandatangan 1','ttd1_jabatan',t.ttd1_jabatan)}${ti('Nama penandatangan 2','ttd2_nama',t.ttd2_nama)}${ti('Jabatan penandatangan 2','ttd2_jabatan',t.ttd2_jabatan)}<label>Stempel ditempatkan pada<select name="stempel_pada" ${ro?'disabled':''}><option value="ttd1" ${t.stempel_pada!=='ttd2'?'selected':''}>Penandatangan 1</option><option value="ttd2" ${t.stempel_pada==='ttd2'?'selected':''}>Penandatangan 2</option></select></label>${ta('Tembusan','tembusan',t.tembusan.join('\n'),3,'satu butir per baris')}${ti('Teks footer','footer',t.footer,true)}</div>${ro?'':`<div style="margin-top:14px">${btn('Kembalikan teks bawaan','sk_reset_template','small danger')}</div>`}`,'Simpan template','sk_template');if(ro)$('#formSubmit').hidden=true}
