`<div class="cards-auto">${cardN('KTA aktif',S.total,'Seluruh tingkat','idcard')}${cardN('DPW',S.DPW,'Provinsi','idcard')}${cardN('DPD',S.DPD,'Kabupaten','idcard')}${cardN('DPC',S.DPC,'Kota','idcard')}${cardN('PAC',S.PAC,'Kecamatan','idcard')}${cardN('Dibatalkan',S.dibatalkan,'Tersimpan sebagai riwayat','idcard','warn')}</div>`+
`<section class="table-panel"><div class="toolbar"><div class="search-wrap">${icon('search')}<input id="ktaQ" placeholder="Cari nama, nomor KTA, atau wilayah" value="${esc(ktaFilter.q)}"></div><select id="ktaTingkat"><option value="">Semua tingkat</option>${Object.keys(KTA_TINGKAT).map(t=>`<option ${ktaFilter.tingkat===t?'selected':''}>${t}</option>`).join('')}</select><select id="ktaStatus">${[['aktif','Aktif'],['dibatalkan','Dibatalkan'],['','Semua status']].map(([v,l])=>`<option value="${v}" ${ktaFilter.status===v?'selected':''}>${l}</option>`).join('')}</select>${btn('Cari','kta_search','')}</div>`+
(d.items.length?`<div class="scroll-x"><table class="data-table"><thead><tr><th>No. KTA</th><th>Nama</th><th>Jabatan</th><th>Wilayah</th><th>Terbit</th><th>Status</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr><td><b>${esc(x.nomor)}</b></td><td>${esc(x.nama)}<br><small class="muted">${esc(x.jenis_kelamin)}</small></td><td>${esc(x.jabatan)} ${esc(x.tingkat)}</td><td>${esc(x.wilayah)}${x.provinsi?`<br><small class="muted">${esc(x.provinsi)}</small>`:''}</td><td>${ktaTerbit(x.terbit)}</td><td>${x.status==='aktif'?status('active'):`<span class="status-pill inactive" title="${esc(x.cancel_note||'')}">Dibatalkan</span>`}</td><td><div class="act-col" style="min-width:170px">${x.status==='aktif'?`<a class="btn small" href="/api/kta/${x.id}/pdf" target="_blank" rel="noopener" title="Lihat dan unduh PDF KTA">PDF</a>${d.can_edit?btn('Ubah','kta_edit','small',`data-id="${x.id}"`)+btn('Batalkan','kta_cancel','small danger',`data-id="${x.id}"`):''}`:''}${btn('Riwayat','kta_hist','small',`data-id="${x.id}"`)}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${fmt(d.total)} kartu · halaman ${d.page} dari ${pages}</span>${btn('‹ Sebelumnya','prev_kta','small',d.page<=1?'disabled':'')}${btn('Berikutnya ›','next_kta','small',d.page>=pages?'disabled':'')}</div>`:empty('Belum ada KTA',d.can_edit?'Klik "+ Buat KTA" untuk menerbitkan kartu pertama.':'KTA yang diterbitkan admin akan tampil di sini.'))+`</section>`;
